/* Тексты документов: редакция от 18 сентября 2026 года (documents.christella.ru). При смене редакции обновить эти данные и DOC_EDITION. */
var DOC_TEXT={"pd":{"title":"ПОЛИТИКА в отношении обработки персональных данных пользователей интернет-ресурсов проекта «Культура вкуса»","ed":"18 сентября 2026 года","blocks":[["h","1. Общие положения"],["p","1.1. Настоящая Политика в отношении обработки персональных данных (далее — Политика) определяет порядок обработки и защиты персональных данных пользователей интернет-ресурсов проекта «Культура вкуса» (далее — Проект)."],["p","1.2. Оператором персональных данных является:"],["p","Индивидуальный предприниматель Никитичева Кристина Эдуардовна"],["p","ИНН: 623015753964"],["p","ОГРНИП: 321623400015060"],["p","Адрес: 390000, Россия, Рязанская область, г. Рязань, ул. Маяковского, д. 49, кв. 141"],["p","E-mail: media_bitch@mail.ru"],["p","далее — Оператор."],["p","1.3. Политика разработана в соответствии с Конституцией Российской Федерации, Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных» и иными применимыми нормативными правовыми актами Российской Федерации в области обработки и защиты персональных данных."],["p","1.4. Политика распространяется на персональные данные, которые Оператор получает при использовании Пользователем интернет-ресурсов Проекта, расположенных на домене https://christella.ru и его субдоменах (поддоменах), сайта, мобильного приложения (при наличии), сервисов и средств автоматизации Проекта, включая чат-боты в Telegram, MAX и ВКонтакте, являющиеся неотъемлемой частью Проекта (далее совместно — Ресурсы Проекта), а также на сведения, необходимые для фиксации факта предоставления или отзыва согласий."],["p","1.5. Оператор ведёт сбор персональных данных на интернет-ресурсах, расположенных на домене https://christella.ru и его субдоменах (поддоменах), а также с использованием средств автоматизации, в том числе чат-ботов Telegram, MAX и ВКонтакте, являющихся неотъемлемой частью Проекта. Использование соответствующих платформ регулируется также их собственными правилами и политиками конфиденциальности; владельцы платформ самостоятельно определяют условия обработки данных в рамках принадлежащей им инфраструктуры."],["p","1.6. Настоящая Политика размещается в свободном доступе на соответствующих Ресурсах Проекта. Продолжая использование сайта, мобильного приложения (при наличии), чат-ботов, сервисов и иных интернет-ресурсов Проекта, а также совершая на них действия, для осуществления которых требуется предоставление или обработка персональных данных, Пользователь подтверждает, что ознакомился с настоящей Политикой и иными применимыми документами Проекта, размещёнными на соответствующем ресурсе. Ознакомление с Политикой и продолжение использования Ресурсов Проекта не заменяют отдельного согласия на обработку персональных данных или отдельного согласия на получение рекламы в случаях, когда получение такого согласия требуется законодательством Российской Федерации."],["h","2. Основные понятия"],["p","2.1. Персональные данные — любая информация, относящаяся прямо или косвенно к определённому или определяемому физическому лицу."],["p","2.2. Пользователь или Субъект персональных данных — физическое лицо, взаимодействующее с Ресурсами Проекта."],["p","2.3. Обработка персональных данных — любое действие или совокупность действий, совершаемых с персональными данными с использованием средств автоматизации или без их использования, включая сбор, запись, систематизацию, накопление, хранение, уточнение, извлечение, использование, передачу в предусмотренных законом случаях, обезличивание, блокирование, удаление и уничтожение персональных данных."],["p","2.4. Автоматизированная обработка персональных данных — обработка персональных данных с помощью средств вычислительной техники."],["p","2.5. Уничтожение персональных данных — действия, в результате которых становится невозможным восстановить содержание персональных данных в информационной системе персональных данных."],["h","3. Принципы обработки персональных данных"],["p","3.1. Оператор осуществляет обработку персональных данных на законной и справедливой основе."],["p","3.2. Обработка персональных данных ограничивается достижением конкретных, заранее определённых и законных целей."],["p","3.3. Не допускается обработка персональных данных, несовместимая с целями их сбора."],["p","3.4. Оператор обрабатывает только те персональные данные, которые необходимы и достаточны для заявленных целей обработки."],["p","3.5. Содержание и объём обрабатываемых персональных данных должны соответствовать заявленным целям обработки."],["p","3.6. Персональные данные не хранятся дольше, чем этого требуют цели обработки или требования законодательства Российской Федерации."],["h","4. Категории и перечень обрабатываемых персональных данных"],["p","Оператор обрабатывает только те персональные данные Пользователя, которые необходимы для заявленных целей обработки."],["p","4.1. Идентификационные и контактные данные"],["li","фамилия;"],["li","имя пользователя (username/никнейм);"],["p","изображение профиля (аватар), если оно доступно соответствующему Ресурсу Проекта;"],["li","номер телефона;"],["li","адрес электронной почты (e-mail);"],["li","идентификатор пользователя в Telegram (Telegram ID);"],["li","идентификатор пользователя в MAX (MAX ID);"],["li","идентификатор пользователя в VK (VK ID)."],["p","4.2. Сведения, подтверждающие предоставление или отзыв согласия"],["li","дата и время предоставления или отзыва согласия;"],["li","вид предоставленного согласия;"],["li","версия (редакция) документа, с которым согласился Пользователь;"],["li","факт совершения подтверждающего действия на соответствующем Ресурсе Проекта, в том числе нажатия соответствующей кнопки."],["p","Указанные сведения обрабатываются исключительно в объёме, необходимом для подтверждения волеизъявления Пользователя и выполнения обязанностей Оператора по законодательству Российской Федерации."],["p","4.3. Источники получения данных"],["p","Фамилия, номер телефона, адрес электронной почты, а также идентификаторы в MAX и VK предоставляются Пользователем самостоятельно. Имя пользователя, идентификатор пользователя и изображение профиля (аватар) могут быть получены Оператором от соответствующей платформы в пределах данных, доступных чат-боту или иному Ресурсу Проекта, и/или предоставлены Пользователем самостоятельно."],["p","4.4. Специальные и биометрические персональные данные"],["p","Оператор не осуществляет целенаправленный сбор и обработку специальных категорий персональных данных, касающихся расовой или национальной принадлежности, политических взглядов, религиозных или философских убеждений, состояния здоровья или интимной жизни."],["p","Оператор не использует изображение профиля (аватар) и иные изображения Пользователя для установления личности и не осуществляет обработку биометрических персональных данных в целях идентификации Пользователя."],["p","Пользователю не следует передавать через Бот специальные категории или биометрические персональные данные."],["h","5. Цели обработки персональных данных"],["p","5.1. Идентификация Пользователя и обеспечение работы Ресурсов Проекта"],["p","Персональные данные обрабатываются для:"],["li","идентификации Пользователя;"],["li","обеспечения доступа к функциям, сервисам и материалам Ресурсов Проекта;"],["li","сопоставления предоставленных Пользователем идентификаторов в Telegram, MAX и VK, когда это необходимо для предоставления сервиса или связи с Пользователем;"],["li","поддержания актуальных контактных данных Пользователя."],["p","5.2. Обратная связь и поддержка"],["p","Персональные данные могут использоваться для:"],["li","ответа на обращения Пользователя;"],["li","оказания технической и пользовательской поддержки;"],["li","идентификации Пользователя при восстановлении доступа или рассмотрении его обращения;"],["li","связи с Пользователем по предоставленным им контактным данным."],["p","5.3. Заключение и исполнение договоров"],["p","Если Пользователь приобретает продукты или услуги Оператора, персональные данные могут использоваться для идентификации стороны договора, связи с Пользователем, предоставления доступа к приобретённым цифровым продуктам, материалам или услугам и исполнения обязательств Оператора перед Пользователем."],["p","Правовым основанием обработки в соответствующих случаях являются согласие Пользователя, заключение или исполнение договора по инициативе Пользователя, а также иные основания, предусмотренные законодательством Российской Федерации."],["p","5.4. Сервисные и организационные сообщения"],["p","Оператор вправе использовать предоставленные Пользователем контактные данные для направления сообщений, объективно необходимых для работы Ресурсов Проекта, исполнения запроса Пользователя или договора, в том числе сообщений о предоставлении доступа, существенных технических изменениях, безопасности и действиях, непосредственно запрошенных Пользователем."],["p","Такие сообщения не являются рекламными, если их содержание связано исключительно с предоставлением запрошенной функции, продукта или услуги."],["p","5.5. Рекламные и маркетинговые сообщения"],["p","Оператор может использовать предоставленные Пользователем контактные данные для направления рекламных, маркетинговых и связанных с ними информационных сообщений только при наличии отдельного предварительного согласия Пользователя на получение рекламных и информационных рассылок."],["p","Пользователь вправе в любой момент отказаться от рекламных и маркетинговых сообщений полностью или по отдельному каналу связи. После получения такого требования Оператор прекращает соответствующую рекламную рассылку."],["p","5.6. Подтверждение согласий и выполнение требований законодательства"],["p","Сведения о дате и времени предоставления или отзыва согласия, виде согласия, редакции документа и факте совершения подтверждающего действия обрабатываются для фиксации и доказательства волеизъявления Пользователя, рассмотрения обращений и исполнения обязанностей Оператора, установленных законодательством Российской Федерации."],["h","6. Правовые основания обработки персональных данных"],["p","Оператор осуществляет обработку персональных данных на следующих основаниях:"],["li","согласие Субъекта персональных данных;"],["li","необходимость обработки для заключения договора по инициативе Субъекта персональных данных или исполнения договора, стороной либо выгодоприобретателем по которому является Субъект персональных данных;"],["li","необходимость выполнения обязанностей, возложенных на Оператора законодательством Российской Федерации;"],["li","осуществление прав и законных интересов Оператора или третьих лиц при условии, что при этом не нарушаются права и свободы Субъекта персональных данных;"],["li","иные основания, прямо предусмотренные законодательством Российской Федерации."],["p","Если обработка осуществляется на основании согласия Пользователя, обязанность подтвердить факт получения такого согласия несёт Оператор."],["h","7. Порядок и способы обработки персональных данных"],["p","7.1. Обработка персональных данных осуществляется с использованием средств автоматизации, включая сайт и иные интернет-ресурсы на домене https://christella.ru и его субдоменах (поддоменах), а также чат-боты Telegram, MAX и ВКонтакте, являющиеся неотъемлемой частью Проекта, а при необходимости — без использования таких средств."],["p","7.2. Оператор может совершать с персональными данными следующие действия: сбор, получение, запись, систематизацию, накопление, хранение, уточнение, обновление, изменение, извлечение, использование, обезличивание, блокирование, удаление, уничтожение, а также предоставление или передачу в случаях и порядке, предусмотренных законодательством Российской Федерации и настоящей Политикой."],["p","7.3. Источниками получения персональных данных являются непосредственно Пользователь, Ресурсы Проекта и соответствующие платформы Telegram, MAX и ВКонтакте — в пределах информации, которую платформа передаёт чат-боту или делает доступной ему вследствие взаимодействия Пользователя. Контактные данные и идентификаторы обрабатываются только в случае их предоставления Пользователем либо их доступности Оператору через используемый Пользователем Ресурс Проекта."],["p","7.4. Оператор не осуществляет продажу персональных данных Пользователей."],["p","7.5. Персональные данные не публикуются и не предоставляются неопределённому кругу лиц без отдельного законного основания."],["h","8. Передача персональных данных третьим лицам"],["p","8.1. В целях обеспечения работы Ресурсов Проекта Оператор вправе привлекать третьих лиц, в частности лиц, обеспечивающих:"],["li","техническое функционирование и хостинг Ресурсов Проекта;"],["li","работу программного обеспечения, CRM-систем и систем автоматизации;"],["li","доставку сервисных и рекламных сообщений по соответствующим каналам связи;"],["li","предоставление цифровых продуктов, материалов или услуг;"],["li","техническую поддержку;"],["li","юридическое, бухгалтерское и иное сопровождение деятельности Оператора."],["p","8.2. Передача или предоставление персональных данных осуществляется только в объёме, необходимом для достижения соответствующей цели, при наличии предусмотренного законодательством основания."],["p","8.3. Если обработка персональных данных поручается другому лицу, отношения с таким лицом оформляются с учётом требований Федерального закона № 152-ФЗ."],["p","8.4. Оператор вправе предоставить персональные данные государственным органам, судам, правоохранительным органам и иным уполномоченным лицам в случаях и порядке, предусмотренных законодательством Российской Федерации."],["p","8.5. Telegram, MAX и VK осуществляют самостоятельную обработку данных Пользователя в рамках собственных информационных систем в соответствии со своими правилами, условиями использования и политиками конфиденциальности в той мере, в которой Пользователь и/или Оператор используют соответствующую платформу для взаимодействия."],["h","9. Локализация и трансграничная передача персональных данных"],["p","9.1. При сборе персональных данных граждан Российской Федерации, в том числе с использованием сети Интернет, Оператор обеспечивает выполнение требований законодательства Российской Федерации о записи, систематизации, накоплении, хранении, уточнении и извлечении персональных данных граждан Российской Федерации с использованием баз данных, находящихся на территории Российской Федерации, кроме случаев, прямо предусмотренных законодательством."],["p","9.2. Бот функционирует на базе платформы Telegram, в связи с чем его работа предполагает технологическое информационное взаимодействие с инфраструктурой Telegram."],["p","9.3. В той части, в которой конкретное техническое взаимодействие Оператора с иностранной информационной системой или иностранным получателем квалифицируется законодательством Российской Федерации как трансграничная передача персональных данных, такая передача осуществляется Оператором только при соблюдении требований статьи 12 Федерального закона № 152-ФЗ."],["p","9.4. До начала осуществления трансграничной передачи персональных данных Оператор выполняет предусмотренные законом обязанности, включая направление отдельного уведомления в уполномоченный орган по защите прав субъектов персональных данных, когда такое уведомление является обязательным."],["p","9.5. Пользователь вправе запросить у Оператора информацию об осуществлённой или предполагаемой трансграничной передаче его персональных данных в порядке, предусмотренном законодательством Российской Федерации."],["h","10. Сроки обработки и хранения персональных данных"],["p","10.1. Персональные данные обрабатываются не дольше, чем этого требуют заявленные цели обработки, если иной срок не установлен законодательством Российской Федерации или договором."],["p","10.2. Идентификационные и контактные данные, необходимые для функционирования Ресурсов Проекта, связи с Пользователем и предоставления соответствующих функций, обрабатываются в течение периода использования Пользователем Ресурсов Проекта и до достижения соответствующей цели обработки, прекращения использования сервиса или получения законного требования о прекращении обработки, если отсутствуют иные законные основания для их хранения."],["p","10.3. Данные, обрабатываемые для заключения и исполнения договора, хранятся в течение срока действия соответствующих договорных отношений, а после их окончания — в течение срока, установленного законодательством Российской Федерации для хранения документов, подтверждения хозяйственных операций и защиты законных прав и интересов Оператора."],["p","10.4. Персональные данные, используемые исключительно для направления рекламных сообщений, обрабатываются до отзыва соответствующего согласия или отказа Пользователя от рекламных сообщений."],["p","10.5. При достижении цели обработки Оператор прекращает обработку соответствующих персональных данных и уничтожает их в срок, не превышающий 30 дней, если иное не предусмотрено законом, договором или иным законным основанием."],["p","10.6. При отзыве согласия на обработку персональных данных Оператор прекращает обработку данных, осуществлявшуюся исключительно на основании такого согласия, и, если сохранение персональных данных более не требуется для иных законных целей, обеспечивает их уничтожение в срок, не превышающий 30 дней с даты получения отзыва."],["p","10.7. Если немедленное уничтожение персональных данных невозможно, Оператор осуществляет их блокирование и обеспечивает уничтожение в сроки, предусмотренные законодательством Российской Федерации."],["h","11. Права Пользователя"],["p","Пользователь вправе:"],["li","получать информацию о факте обработки его персональных данных;"],["li","получать сведения о целях и правовых основаниях обработки;"],["li","получать сведения о категориях и составе обрабатываемых персональных данных;"],["li","получать информацию об источниках получения персональных данных;"],["li","получать информацию о сроках обработки и хранения;"],["li","получать информацию о лицах, осуществляющих обработку персональных данных по поручению Оператора;"],["li","получать информацию об осуществлённой или предполагаемой трансграничной передаче персональных данных;"],["li","требовать уточнения своих персональных данных;"],["li","требовать блокирования или уничтожения данных, если они являются неполными, устаревшими, неточными, незаконно полученными либо не требуются для заявленной цели обработки;"],["li","отозвать ранее предоставленное согласие на обработку персональных данных;"],["li","потребовать прекратить обработку персональных данных, за исключением случаев, когда Оператор вправе или обязан продолжать обработку на ином предусмотренном законом основании;"],["li","отказаться от получения рекламных сообщений;"],["li","обжаловать действия или бездействие Оператора в Роскомнадзор или в судебном порядке;"],["li","осуществлять иные права, предусмотренные законодательством Российской Федерации."],["h","12. Порядок направления обращений и отзыва согласия"],["p","12.1. Пользователь вправе направить Оператору обращение, запрос, требование о прекращении обработки либо отзыв согласия на обработку персональных данных по адресу электронной почты: media_bitch@mail.ru или по почтовому адресу: 390000, Россия, Рязанская область, г. Рязань, ул. Маяковского, д. 49, кв. 141."],["p","12.2. Для идентификации Субъекта персональных данных в обращении рекомендуется указать один или несколько имеющихся у Оператора идентификаторов: Telegram ID, MAX ID, VK ID, имя пользователя (username/никнейм), номер телефона или адрес электронной почты. Оператор не требует предоставления избыточных сведений, не необходимых для рассмотрения обращения."],["p","12.3. Оператор вправе запросить дополнительные сведения, необходимые для подтверждения личности заявителя и предотвращения неправомерного доступа к данным третьих лиц."],["p","12.4. Запросы Субъектов персональных данных рассматриваются в сроки, предусмотренные Федеральным законом № 152-ФЗ."],["p","12.5. Отзыв согласия не влияет на законность обработки, осуществлявшейся до момента его получения Оператором."],["p","12.6. После отзыва согласия Оператор вправе продолжить обработку персональных данных в случаях, прямо предусмотренных законодательством Российской Федерации."],["h","13. Защита персональных данных"],["p","13.1. Оператор принимает необходимые и достаточные правовые, организационные и технические меры для защиты персональных данных от:"],["li","неправомерного или случайного доступа;"],["li","уничтожения;"],["li","изменения;"],["li","блокирования;"],["li","копирования;"],["li","предоставления;"],["li","распространения;"],["li","иных неправомерных действий."],["p","13.2. В частности, Оператор с учётом характера обработки и используемых информационных систем применяет необходимые меры по:"],["li","ограничению круга лиц, имеющих доступ к персональным данным;"],["li","контролю доступа к информационным системам;"],["li","использованию средств идентификации и аутентификации;"],["li","обеспечению конфиденциальности персональных данных;"],["li","защите информационных систем и средств доступа;"],["li","выявлению и устранению нарушений;"],["li","контролю соблюдения требований законодательства о персональных данных;"],["li","резервному копированию и восстановлению информации, когда это необходимо;"],["li","реагированию на инциденты безопасности;"],["li","уничтожению персональных данных после прекращения законных оснований для их обработки."],["p","13.3. Доступ к персональным данным предоставляется только лицам, которым он необходим для выполнения соответствующих функций."],["h","14. Действия при инцидентах безопасности"],["p","14.1. При выявлении факта неправомерной или случайной передачи, предоставления, распространения либо доступа к персональным данным, повлекшего нарушение прав Субъектов персональных данных, Оператор принимает предусмотренные законодательством Российской Федерации меры."],["p","14.2. Оператор проводит внутреннее расследование обстоятельств инцидента, принимает меры по устранению его последствий и выполняет установленные законом обязанности по взаимодействию с уполномоченным органом по защите прав субъектов персональных данных."],["h","15. Изменение Политики"],["p","15.1. Оператор вправе изменять настоящую Политику при изменении законодательства Российской Федерации, функциональности Ресурсов Проекта, состава обрабатываемых данных или порядка их обработки."],["p","15.2. Новая редакция Политики вступает в силу с момента её публикации, если иной срок не указан в самой новой редакции."],["p","15.3. Если изменения существенно затрагивают условия обработки персональных данных, Оператор вправе дополнительно уведомить Пользователей через Бот."],["p","15.4. Если в связи с изменениями требуется получение нового согласия Пользователя, Оператор запрашивает такое согласие отдельно."],["h","16. Заключительные положения"],["p","16.1. Настоящая Политика действует бессрочно до её замены новой редакцией."],["p","16.2. По вопросам обработки и защиты персональных данных Пользователь может обратиться к Оператору:"],["p","Индивидуальный предприниматель Никитичева Кристина Эдуардовна"],["p","ИНН: 623015753964"],["p","ОГРНИП: 321623400015060"],["p","Адрес: 390000, Россия, Рязанская область, г. Рязань, ул. Маяковского, д. 49, кв. 141"],["p","E-mail: media_bitch@mail.ru"],["p","Дата публикации и вступления в силу настоящей редакции: 18 сентября 2026 года."]]},"cons":{"title":"СОГЛАСИЕ на обработку персональных данных","ed":"18 сентября 2026 года","blocks":[["p","Совершая на соответствующем Ресурсе Проекта отдельное действие, однозначно подтверждающее предоставление согласия на обработку персональных данных, я свободно, своей волей и в своём интересе предоставляю:"],["p","Индивидуальный предприниматель Никитичева Кристина Эдуардовна"],["p","ИНН: 623015753964"],["p","ОГРНИП: 321623400015060"],["p","Адрес: 390000, Россия, Рязанская область, г. Рязань, ул. Маяковского, д. 49, кв. 141"],["p","E-mail: media_bitch@mail.ru"],["p","далее — Оператор, на следующих условиях."],["h","1. Перечень персональных данных"],["p","Оператор вправе обрабатывать следующие мои персональные данные:"],["li","фамилию;"],["li","имя пользователя (username/никнейм);"],["li","изображение профиля (аватар), если оно доступно соответствующему Ресурсу Проекта;"],["li","номер телефона;"],["li","адрес электронной почты (e-mail);"],["li","идентификатор пользователя в Telegram (Telegram ID);"],["li","идентификатор пользователя в MAX (MAX ID);"],["li","идентификатор пользователя в VK (VK ID);"],["li","сведения о предоставлении или отзыве настоящего и иных согласий: дату и время, вид согласия, редакцию документа и факт совершения подтверждающего действия на соответствующем Ресурсе Проекта."],["p","Оператор не осуществляет целенаправленный сбор специальных категорий персональных данных или биометрических персональных данных для целей установления личности."],["h","2. Цели обработки"],["p","Я предоставляю согласие на обработку персональных данных в целях:"],["li","регистрации и идентификации меня как Пользователя соответствующего Ресурса Проекта;"],["li","обеспечения работы интернет-ресурсов проекта «Культура вкуса» и предоставления доступа к их функциям, сервисам и материалам;"],["li","сопоставления предоставленных мной идентификаторов в Telegram, MAX и VK, когда это необходимо для предоставления сервиса или связи со мной;"],["li","поддержания актуальных контактных данных;"],["li","обратной связи, рассмотрения обращений и оказания технической поддержки;"],["li","идентификации меня при восстановлении доступа или рассмотрении обращения;"],["li","направления сервисных и организационных сообщений, необходимых для предоставления запрошенных функций, материалов, продуктов или услуг;"],["li","заключения и исполнения договоров по моей инициативе, в том числе предоставления доступа к приобретённым цифровым продуктам, материалам или услугам;"],["li","фиксации и подтверждения факта предоставления или отзыва согласий;"],["li","выполнения требований законодательства Российской Федерации."],["p","Использование моих персональных данных для направления рекламных и маркетинговых сообщений допускается только при наличии отдельного согласия на получение рекламных и информационных рассылок."],["h","3. Действия с персональными данными"],["p","Настоящим я предоставляю Оператору право совершать с моими персональными данными следующие действия: сбор, запись, систематизацию, накопление, хранение, уточнение, обновление, изменение, извлечение, использование, предоставление лицам, осуществляющим обработку персональных данных по поручению Оператора, в объёме и случаях, необходимых для достижения заявленных целей, обезличивание, блокирование, удаление и уничтожение."],["p","Обработка осуществляется с использованием средств автоматизации и, при необходимости, без использования средств автоматизации."],["p","Настоящее согласие само по себе не является согласием на распространение моих персональных данных неопределённому кругу лиц."],["h","4. Обработка персональных данных другими лицами"],["p","Я уведомлён(а), что для обеспечения функционирования интернет-ресурсов проекта «Культура вкуса», работы информационных систем, CRM, доставки сообщений, предоставления цифровых материалов или услуг и иных заявленных целей Оператор вправе поручать обработку персональных данных другим лицам в порядке и на условиях, предусмотренных законодательством Российской Федерации."],["p","Лица, осуществляющие обработку персональных данных по поручению Оператора, обязаны соблюдать конфиденциальность и обеспечивать безопасность персональных данных."],["p","Передача персональных данных государственным органам и иным лицам может осуществляться также в случаях, предусмотренных законодательством Российской Федерации."],["h","5. Сайт, сервисы, Telegram, MAX и ВКонтакте"],["p","Я понимаю, что сбор персональных данных осуществляется на интернет-ресурсах, расположенных на домене https://christella.ru и его субдоменах (поддоменах), а также с использованием средств автоматизации, в том числе чат-ботов Telegram, MAX и ВКонтакте, являющихся неотъемлемой частью проекта «Культура вкуса»."],["p","Telegram, MAX и ВКонтакте самостоятельно определяют условия обработки данных в рамках принадлежащей им инфраструктуры в соответствии со своими правилами и политиками конфиденциальности."],["p","Имя пользователя, идентификатор пользователя и изображение профиля (аватар) могут быть получены Оператором от соответствующей платформы в пределах данных, доступных чат-боту, и/или предоставлены мной самостоятельно. Изображение профиля не используется Оператором для установления моей личности или биометрической идентификации."],["p","Настоящее Согласие регулирует обработку персональных данных Оператором на интернет-ресурсах проекта «Культура вкуса», включая сайт и иные ресурсы домена https://christella.ru и его субдоменов (поддоменов), сервисы и чат-боты Telegram, MAX и ВКонтакте, а также лицами, которым Оператор законно поручает такую обработку."],["h","6. Срок действия согласия"],["p","Настоящее согласие действует с момента его предоставления до достижения целей обработки персональных данных либо до момента его отзыва мной, если более длительная обработка или хранение не требуется и не допускается на ином основании, предусмотренном законодательством Российской Федерации."],["p","После достижения целей обработки или отзыва согласия Оператор прекращает обработку персональных данных, осуществлявшуюся исключительно на основании настоящего согласия, если отсутствуют иные законные основания для её продолжения."],["h","7. Отзыв согласия"],["p","Я вправе в любой момент отозвать настоящее согласие полностью или в соответствующей части."],["p","Для этого я могу направить Оператору заявление по адресу: media_bitch@mail.ru."],["p","В обращении необходимо указать сведения, позволяющие Оператору идентифицировать меня как Пользователя соответствующего Ресурса Проекта, например:"],["li","Telegram ID, MAX ID или VK ID;"],["li","имя пользователя (username/никнейм);"],["li","номер телефона или адрес электронной почты, если они были предоставлены Оператору."],["p","Отзыв согласия не влияет на законность обработки персональных данных, осуществлённой до момента получения Оператором соответствующего отзыва."],["p","Если после отзыва согласия существуют иные предусмотренные законодательством Российской Федерации основания для обработки отдельных персональных данных, Оператор вправе продолжить их обработку исключительно в пределах таких оснований."],["h","8. Подтверждение согласия"],["p","Предоставление согласия подтверждается отдельным однозначным действием на соответствующем Ресурсе Проекта, например нажатием кнопки, установлением отдельной отметки либо направлением формы, рядом с которыми размещена ссылка на настоящее Согласие и ясно указано, что совершаемое действие означает согласие на обработку персональных данных. Простое продолжение использования Ресурсов Проекта без такого подтверждающего действия не считается предоставлением настоящего Согласия."],["p","Оператор вправе фиксировать и хранить сведения, подтверждающие факт предоставления согласия, в том числе:"],["li","идентификатор пользователя в мессенджере, через который предоставлено согласие (в том числе Telegram ID, MAX ID или VK ID);"],["li","дату и время предоставления согласия;"],["li","идентификатор или номер редакции настоящего Согласия;"],["li","вид и факт совершения подтверждающего действия на соответствующем Ресурсе Проекта."],["p","Указанные сведения могут использоваться Оператором для подтверждения факта получения согласия."],["p","Перед предоставлением согласия мне предоставлена возможность ознакомиться с Политикой в отношении обработки персональных данных пользователей интернет-ресурсов проекта «Культура вкуса»."]]},"mkt":{"title":"СОГЛАСИЕ на получение рекламных и информационных рассылок","ed":"18 сентября 2026 года","blocks":[["p","Совершая на соответствующем Ресурсе Проекта отдельное действие, однозначно подтверждающее согласие на получение рекламных и информационных рассылок, я свободно, своей волей и в своём интересе предоставляю:"],["p","Индивидуальный предприниматель Никитичева Кристина Эдуардовна"],["p","ИНН: 623015753964"],["p","ОГРНИП: 321623400015060"],["p","Адрес: 390000, Россия, Рязанская область, г. Рязань, ул. Маяковского, д. 49, кв. 141"],["p","E-mail: media_bitch@mail.ru"],["p","далее — Оператор, своё предварительное согласие на получение от Оператора рекламных, маркетинговых и информационных сообщений на следующих условиях."],["h","1. Что я соглашаюсь получать"],["p","Я соглашаюсь получать от Оператора по каналам связи, указанным в разделе 2 настоящего Согласия:"],["li","новости проекта «Культура вкуса»;"],["li","анонсы новых материалов;"],["li","информацию о новых продуктах и услугах Оператора;"],["li","информацию о книгах, гайдах, подборках, курсах, интенсивах, подписках и иных цифровых продуктах;"],["li","информацию о мероприятиях, эфирах, обучающих программах и специальных проектах;"],["li","персональные и общие предложения;"],["li","информацию о скидках, акциях, специальных условиях и промокодах;"],["li","рекомендации продуктов, материалов и услуг;"],["li","маркетинговые и рекламные материалы Оператора;"],["li","рекламные интеграции и информацию о товарах, работах или услугах третьих лиц, распространяемую Оператором по указанным в разделе 2 каналам связи без передачи моих персональных данных соответствующим рекламодателям, если иное отдельно не согласовано со мной;"],["li","опросы, исследования и предложения дать обратную связь;"],["li","иные информационно-рекламные сообщения, относящиеся к деятельности Оператора и проекту «Культура вкуса»."],["p","Настоящее согласие не распространяется на рекламу, распространение которой запрещено законодательством Российской Федерации."],["h","2. Канал направления сообщений"],["p","Настоящее Согласие предоставляется на получение рекламных, маркетинговых и связанных с ними информационных сообщений по тем контактным данным, которые я предоставил(а) Оператору:"],["li","в Telegram — по Telegram ID и/или имени пользователя;"],["li","в MAX — по MAX ID;"],["li","в VK — по VK ID;"],["li","по электронной почте — на предоставленный адрес e-mail;"],["li","посредством SMS или иных текстовых сообщений — на предоставленный номер телефона, если Оператор использует такой канал."],["p","Настоящее Согласие не включает рекламные голосовые телефонные звонки, если отдельное согласие на них не получено."],["p","Оператор использует только те каналы связи, контактные данные для которых фактически предоставлены мной и в отношении которых действует настоящее Согласие."],["h","3. Персональные данные, используемые для рассылки"],["p","Для направления рассылки Оператор вправе использовать только следующие предоставленные мной персональные данные:"],["li","фамилию;"],["li","имя пользователя (username/никнейм);"],["li","изображение профиля (аватар), если оно доступно соответствующему Ресурсу Проекта;"],["li","номер телефона;"],["li","адрес электронной почты (e-mail);"],["li","Telegram ID;"],["li","MAX ID;"],["li","VK ID."],["p","Эти данные используются для идентификации адресата, выбора доступного канала связи и доставки сообщений. Поведенческое профилирование на основании истории действий на Ресурсах Проекта настоящим Согласием не предусматривается."],["h","4. Отличие рекламной рассылки от сервисных сообщений"],["p","Я понимаю, что настоящее Согласие относится к рекламным, маркетинговым и связанным с ними информационным рассылкам."],["p","Сообщения, непосредственно необходимые для исполнения моего запроса, предоставления запрошенной функции Ресурса Проекта, исполнения заключённого со мной договора, предоставления доступа к приобретённому продукту или материалу, обеспечения безопасности, информирования о существенных технических изменениях либо выполнения требований законодательства Российской Федерации, могут направляться Оператором по предоставленным мной контактным данным независимо от действия настоящего Согласия при наличии соответствующего законного основания и если такие сообщения не имеют рекламного характера."],["h","5. Добровольность согласия"],["p","Предоставление настоящего Согласия является добровольным."],["p","Отказ от рекламной рассылки сам по себе не ограничивает возможность использовать функции интернет-ресурсов проекта «Культура вкуса», для которых получение рекламных сообщений объективно не требуется."],["p","Согласие на обработку персональных данных и настоящее Согласие на получение рекламных и информационных рассылок предоставляются отдельно."],["h","6. Срок действия"],["p","Настоящее Согласие действует с момента его предоставления до момента моего отказа от получения соответствующих сообщений либо до прекращения Оператором соответствующей рассылки."],["h","7. Отказ от рассылки"],["p","Я вправе в любой момент и без объяснения причин отказаться от получения рекламных и маркетинговых сообщений."],["p","Отказ может быть осуществлён:"],["li","посредством функции «Отписаться от рассылки» в Telegram-боте, если такая функция доступна;"],["li","путём направления требования на электронную почту: media_bitch@mail.ru. В требовании можно указать, от каких каналов необходимо отказаться: от всех рассылок либо только от Telegram, MAX, VK, e-mail или сообщений на номер телефона. Для идентификации адресата достаточно указать один или несколько известных Оператору идентификаторов: Telegram ID, MAX ID, VK ID, имя пользователя, номер телефона или e-mail."],["p","После получения отказа Оператор прекращает направление мне рекламных сообщений."],["p","Отказ от рекламной рассылки не означает автоматический отзыв согласия на обработку всех персональных данных и не прекращает обработку персональных данных, осуществляемую Оператором на иных законных основаниях."],["h","8. Подтверждение предоставления согласия"],["p","Предоставление настоящего Согласия подтверждается отдельным однозначным действием на соответствующем интернет-ресурсе проекта «Культура вкуса», расположенном на домене https://christella.ru или его субдомене (поддомене), либо в чат-боте Telegram, MAX или ВКонтакте, например нажатием кнопки, установлением отдельной отметки или направлением формы, рядом с которыми размещена ссылка на настоящее Согласие и ясно указано, что совершаемое действие означает согласие на получение рекламных и информационных рассылок. Простое продолжение использования Ресурсов Проекта без такого подтверждающего действия не считается предоставлением настоящего Согласия."],["p","Оператор вправе фиксировать и хранить сведения, подтверждающие факт предоставления настоящего Согласия, в том числе:"],["li","идентификатор пользователя в мессенджере, через который предоставлено согласие (в том числе Telegram ID, MAX ID или VK ID);"],["li","дату и время предоставления Согласия;"],["li","идентификатор или номер редакции настоящего документа;"],["li","вид и факт совершения подтверждающего действия на соответствующем Ресурсе Проекта."],["p","Такие сведения могут использоваться для подтверждения наличия предварительного согласия адресата на получение рекламы."]]}};
